      SUBROUTINE WOBBLECC     CALCULATES PARTIAL DERIVATIVES OF BEAM MATRIX WITH RESPECT TOC     MISALIGNMENT PARAMETERSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8E.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'      INTEGER         I2MOD, J, K, M, N      REAL            S, ZAP      C      I2MOD = 2 - MOD(JV,2)      IF (LFM .NE. 0) GO TO 100CC     UNCERTAIN MISALIGNMENTC      DO 50 J = 1, 6      DO 50 K = 1, J      S = 0.0      IF (.NOT. FEO) S = CT(J,JV)*CT(K,JV)      IF (J .LE. 5) THEN        IF (SPO(IR)) THEN          DO 10 M = 1, 6          S = S + (CT(J,JV)*GT(K,M,JV) + CT(K,JV)*GT(J,M,JV))*COLD(IR,M)   10     CONTINUE        ENDIF        DO 30 M = 1, 6        DO 30 N = 1, 6        ZAP = GT(J,M,JV)*GT(K,N,JV)*SIOL(IR,M,N)        S = S + ZAP   30   CONTINUE      ENDIFC      S = 2.0*S*VM(JV)*UMIS(I2MOD)      IF (.NOT. SVP(NV2)) THEN        SV(J,K,NV2) = S      ELSE        SV(J,K,NV2) = SV(J,K,NV2) + S      ENDIF      SV(K,J,NV2) = SV(J,K,NV2)   50 CONTINUE      SVP(NV2) = .TRUE.      GO TO 200CC     KNOWN MISALIGNMENTC  100 IF (BEFORE) CALL DEMENT      IF (.NOT. BEFORE) CALL DEMEXC  200 RETURN      END